const page = await figma.getNodeByIdAsync("3:2");
const byName={};for(const f of page.children) if(f.type==="FRAME") byName[f.name]=f;
const explore=byName["05_Explore_Products"], filter=byName["06_Filter"];
const sheet=filter.findOne(n=>n.name==="Filter · Bottom Sheet");
const moved=[];
for(const c of [...explore.children]){if(c.type==="FRAME"&&c.name.startsWith("Chip · ")&&c.y<150){
  const ox=c.x,oy=c.y;sheet.appendChild(c);c.x=ox;c.y=oy;moved.push(c.name);}}
const sheetChips=sheet.findAll(n=>n.type==="FRAME"&&n.name.startsWith("Chip")).map(n=>n.name+":"+Math.round(n.y));
return JSON.stringify({moved,sheetChips,exploreChips:explore.findAll(n=>n.type==="FRAME"&&n.name.startsWith("Chip")).map(n=>n.name+":"+Math.round(n.y))});

const page = await figma.getNodeByIdAsync("3:2");
const rows=[];
for(const f of page.children){if(f.type!=="FRAME")continue;
  const links=f.findAll(n=>n.reactions&&n.reactions.length>0).map(n=>{const d=n.reactions[0].actions[0].destinationId;const t=figma.getNodeById(d);return n.name+"→"+(t?t.name:"?");});
  rows.push({frame:f.name,id:f.id,size:Math.round(f.width)+"x"+Math.round(f.height),links});}
return JSON.stringify(rows,null,1);
